    const kindSel = h("select", { "aria-label": "Add" }, h("option", { value: "" }, PORT_SAVED.editing ? `Editing: ${PT.ED_PORT_LABEL[kind               ]}` : "Add…"), ...kinds.map((k) => h("option", { value: k, selected: k === kind ? true : undefined }, PT.ED_PORT_LABEL[k])))                     ;
    kindSel.addEventListener("change", () => { PORT_SAVED.kind = kindSel.value                    ; PORT_SAVED.editing = ""; PORT_SAVED.spec = null; render(); });
    v.append(h("div", { style: "margin-top:8px" }, kindSel));
