      show();
      const det = h("details", {}, h("summary", {}, "Choose…"), items.length ? picker(items, (n) => { set(n.def .symbol); show(); showPlan(null); }, ix.bySymbol.get(get() ?? "") ?? "").el : h("div", { class: "empty", style: "padding:6px" }, "No eligible notes."));
